<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\Holder\UserConsentPurposesUserAgentAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentPurposesUserAgentAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserConsentPurposesUserAgentAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getUserAgent returns null on a freshly created holder.
     */
    public function testUserAgentNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentPurposesUserAgentAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUserAgentAssigned());
        $this->assertNull($holder->getUserAgent());
    }
}
class ImplWithUserConsentPurposesUserAgentAttributeHolderUnitTest
{
    use UserConsentPurposesUserAgentAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUserAgentRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUserAgent();
    }
}
